function showView(view,updateLink=true){if(isStockAssistant())view='dashboard';if(!$('#'+view))view='dashboard';$$('.view').forEach(v=>v.classList.toggle('active-view',v.id===view));$$('.nav-link').forEach(v=>v.classList.toggle('active',v.dataset.view===view));const names={dashboard:'Business overview',expenses:'Expenses / Cash Out',receivables:'Accounts receivable',payables:'Accounts payable',contacts:'Contacts',reports:'Reports'};$('#page-title').textContent=names[view];$('#add-record').style.display='';if(updateLink&&location.hash!==`#${view}`)history.replaceState({sarmartApp:'active'},'',`#${view}`);window.scrollTo({top:0,behavior:'smooth'});}function canSearchEdit(record){const role=String(currentUser?.role||'');return currentUser?.role==='admin'||((role==='assistant'||role.startsWith('assistant-'))&&record.type!=='expense');}function renderRecordSearch(){const target=$('#record-search-results'),query=$('#record-search-input').value.trim().toLowerCase();if(!query){target.innerHTML='<p class="record-search-empty">Type a supplier, customer, or description to find an entry.</p>';return;}const matches=records.filter(record=>canSearchEdit(record)&&`${record.party} ${record.name} ${record.category} ${record.notes} ${noteEntries(record).map(note=>note.text).join(' ')}`.toLowerCase().includes(query)).slice(0,60);target.innerHTML=matches.length?matches.map(record=>`<button type="button" class="record-search-result" data-open-search-record="${esc(record.id)}"><span><strong>${esc(record.party||record.name||'Untitled entry')}</strong><small>${esc(typeName(record.type))} · ${esc(record.type==='expense'?record.category||'Other':record.name||'')}</small></span><strong class="amount ${record.type}">${money.format(record.amount)}</strong></button>`).join(''):'<p class="record-search-empty">No matching entries found.</p>';}
